import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // ------- Backdrop Plane (stage void avoidance) -------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // Vertical gradient from surface to ink
  const surfaceCol = color('#0b0b10');
  const inkCol = color('#16161d');
  const uvNode = uv();
  backdropMat.colorNode = mix(surfaceCol, inkCol, uvNode.y);
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ------- Textured Content Plane -------
  // Image aspect 512x320 ≈ 1.6:1
  const planeGeom = new PlaneGeometry(1.6, 1);
  const planeMat = new MeshBasicNodeMaterial({ map: null });
  const plane = new Mesh(planeGeom, planeMat);

  // Load texture asynchronously (function remains sync)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ------- Text Content -------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly above plane center
    txt.position.set(0, 0.4, 0.01);
    plane.add(txt);
  }

  root.add(plane);

  // ------- Apply Cinematic Primitives (if any) -------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && prim.name && ctx.primitives[prim.name]) {
        const handle = ctx.primitives[prim.name](root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // ------- Entrance Animation (optional, follows spec) -------
  const timelines = [];
  const entrance = gsap.timeline();
  entrance.from(root.position, {
    y: root.position.y + 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(entrance);

  // ------- Set Transform from Config -------
  const pos = config.position ?? config.scenePosition ?? { x: 0, y: 0, z: 0 };
  root.position.set(
    typeof pos === 'object' && 'x' in pos ? pos.x : pos[0] ?? 0,
    typeof pos === 'object' && 'y' in pos ? pos.y : pos[1] ?? 0,
    typeof pos === 'object' && 'z' in pos ? pos.z : pos[2] ?? 0
  );

  const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
  root.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);

  const scl = config.scale ?? { x: 1, y: 1, z: 1 };
  root.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  // ------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((p) => p && typeof p.cleanup === 'function' && p.cleanup());
    backdropGeom.dispose();
    backdropMat.dispose();
    planeGeom.dispose();
    planeMat.dispose();
    if (planeMat.map) planeMat.map.dispose();
  };

  return root;
}
